 *  and so on, each once. */
export function useFamily(sheet: string) {
  return useQuery({
    queryKey: familyKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/family`),
  });
}

