import { useState } from 'react';
import type { FormEvent } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { fetchSnapshotCompare } from './snapshots';

// Compares two snapshot dates: per person in list order, their due-total in the SNAPSHOT written on leaving the
// from-date, then likewise for the to-date (or their due-total now when it is blank). A blank from-date is the
// sheet's today.
function SnapshotCompare({ sheet }: { sheet: string; user: string }) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [lines, setLines] = useState<string[]>([]);

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    // The old lines go as soon as the comparison is asked for again.
    setLines([]);
    setLines(await fetchSnapshotCompare(sheet, from.trim(), to.trim()));
  };

  return (
    <form onSubmit={submit}>
      Compare snapshots:{' '}
      <input data-testid="snapshot-from" type="text" placeholder="from yyyy-mm-dd" value={from}
        onChange={(e) => setFrom(e.target.value)} />{' '}
      <input data-testid="snapshot-to" type="text" placeholder="to yyyy-mm-dd" value={to}
        onChange={(e) => setTo(e.target.value)} />{' '}
      <button type="submit" data-testid="snapshot-compare">
        Compare
      </button>
      {lines.map((line, i) => (
        <div key={i} data-testid="snapshot-line">
          {line}
        </div>
      ))}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 85, Component: SnapshotCompare });
import { createContext, useContext } from 'react';
import { getJson, getJsonNow } from '../api/http';
import { asString, useSearchParam } from '../url/useSearchParam';

/** Set around a part of the screen that shows the sheets as they are now even while the screen shows the sheet as
 *  of a date (the search results). */
export const LiveFigures = createContext(false);

/** The query key and the read a sheet query uses: its own, or, inside {@link LiveFigures} while an as-of date is
 *  set, a key of its own ('live' first) read as the sheet is now. With no as-of date the two are the same query. */
export function useReadScope<K extends readonly unknown[]>(key: K): { key: readonly unknown[]; get: typeof getJson } {
  const live = useContext(LiveFigures);
  const [asof] = useSearchParam('asof', asString);
  return live && asof ? { key: ['live', ...key], get: getJsonNow } : { key, get: getJson };
}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});

